local function __bxor_str(data, key)
    local out = table.create(#data)
    local kl = #key
    for i = 0x1, #data do
        out[i] = string.char(bit32.bxor(string.byte(data, i), key[((i - 0x1) % kl) + 0x1]))
    end
    return table.concat(out)
end

local function __b64dec(data)
