    local inv = {}
    for i = 0x1, #b do inv[string.sub(b, i, i)] = i - 0x1 end
    data = string.gsub(data, "[^%w%+%/%=]", "")
    local out = {}
    local n, buf = 0x0, 0x0
    for i = 0x1, #data do
        local c = string.sub(data, i, i)
        if c ~= "=" then
            buf = buf * 0x40 + (inv[c] or 0x0)
            n = n + 0x6
            if n >= 0x8 then
                n = n - 0x8
                out[#out + 0x1] = string.char(math.floor(buf / (0x2 ^ n)) % 0x100)
                buf = buf % (0x2 ^ n)
            end
        end
    end
    return table.concat(out)
